 private String normalize(String path){return LibraryRepository.normalize(path);}
 private boolean blocked(String folder){String f=normalize(folder);for(String x:excluded)if(f.equals(normalize(x))||f.startsWith(normalize(x)+"/"))return true;return false;}
 private String mediaPermission(){return Build.VERSION.SDK_INT>=33?"android.permission.READ_MEDIA_VIDEO":Manifest.permission.READ_EXTERNAL_STORAGE;}
 private void permission(){ArrayList<String> wanted=new ArrayList<>();if(checkSelfPermission(mediaPermission())!=PackageManager.PERMISSION_GRANTED)wanted.add(mediaPermission());if(Build.VERSION.SDK_INT>=34&&checkSelfPermission("android.permission.READ_MEDIA_VISUAL_USER_SELECTED")!=PackageManager.PERMISSION_GRANTED)wanted.add("android.permission.READ_MEDIA_VISUAL_USER_SELECTED");if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)wanted.add("android.permission.POST_NOTIFICATIONS");if(!wanted.isEmpty())requestPermissions(wanted.toArray(new String[0]),8);else scan();}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(code==42){if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED)commitRename();else{pendingRename=null;toast("No se autorizó el cambio de nombre.");}return;}if(code==32){VideoItem item=pendingDelete;pendingDelete=null;if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED&&item!=null)deleteVideo(item);else toast("No se concedió permiso para eliminar.");}scan();}
 private void scan(){final int token=++scanToken;scanner.execute(()->{List<VideoItem> result;
  try{result=libraryRepository.load();}catch(SecurityException e){result=Collections.emptyList();}catch(Exception e){handler.post(()->toast("No se pudo actualizar la biblioteca."));return;}
  final List<VideoItem> loaded=result;handler.post(()->{if(isFinishing()||isDestroyed()||token!=scanToken)return;videos.clear();videos.addAll(loaded);renderRows();});
 });}
 private void pickFile(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("video/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,20);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==40||request==41){if(result==RESULT_OK)commitRename();else{pendingRename=null;toast("Cambio de nombre cancelado.");}return;}if(request==30||request==31){VideoItem item=pendingDelete;pendingDelete=null;if(result==RESULT_OK&&item!=null){if(request==31)deleteVideo(item);else deleted(item);}else if(item!=null)toast("Eliminación cancelada");return;}if(request==32){if(result==RESULT_OK&&pendingDelete!=null){VideoItem item=pendingDelete;pendingDelete=null;deleteVideo(item);}else{pendingDelete=null;toast("No se concedió permiso para eliminar.");}return;}if(request==21&&result==RESULT_OK&&data!=null&&playback!=null&&playback.current()!=null){Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException e){}if(pendingSubtitleVideo==null||!pendingSubtitleVideo.equals(playback.current().uri)){toast("El vídeo cambió mientras seleccionabas el subtítulo. Vuelve a cargarlo para el vídeo actual.");return;}subtitleVideo=pendingSubtitleVideo;pendingSubtitleVideo=null;loadSubtitle(uri,subtitleVideo);return;}if(request==20&&result==RESULT_OK&&data!=null){Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException e){}if(playback==null)pendingUri=uri;else openExternal(uri);}}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(intent.getData()!=null){if(playback==null)pendingUri=intent.getData();else openExternal(intent.getData());}else if(playback!=null&&playback.current()!=null)showPlayer();}
 private void openExternal(Uri uri){String name="Vídeo";try(Cursor c=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}catch(Exception e){}startVideo(Collections.singletonList(new VideoItem(uri,name,"Archivo seleccionado",0)),0);}
 private void startVideo(List<VideoItem> queue,int selected){if(playback==null){toast("Preparando reproductor…");return;}startForegroundService(new Intent(this,PlaybackService.class));playback.setQueue(queue,selected);prefs.edit().putInt("imageMode",prefs.getInt("imageMode:"+queue.get(selected).uri,prefs.getInt("imageMode",0))).apply();showPlayer();}
