 private void fitVideo(){if(surface==null||stage==null||playback==null||!playback.prepared)return;int w=playback.videoWidth(),h=playback.videoHeight();if(w<=0||h<=0)return;int sw=stage.getWidth(),sh=stage.getHeight();if(sw<=0||sh<=0)return;int mode=prefs.getInt("imageMode",0);double ratio=(mode==1?Math.max((double)sw/w,(double)sh/h):Math.min((double)sw/w,(double)sh/h))*zoom;FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(mode==2?sw:(int)(w*ratio),mode==2?sh:(int)(h*ratio),Gravity.CENTER);if(surface.getLayoutParams().width!=p.width||surface.getLayoutParams().height!=p.height)surface.setLayoutParams(p);}
 private void scheduleHide(){handler.removeCallbacks(hideControls);if(!isInPictureInPictureMode())handler.postDelayed(hideControls,prefs.getInt("hideSeconds",4)*1000L);}
 private int step(){return prefs.getInt("seekSeconds",5);}
 private void hud(String value){feedback.setText("  "+value+"  ");feedback.setVisibility(View.VISIBLE);handler.removeCallbacks(hideFeedback);handler.postDelayed(hideFeedback,1200);}
 private void gestures(View touch){
  ScaleGestureDetector scale=new ScaleGestureDetector(this,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){zoom=Math.max(1f,Math.min(3f,zoom*d.getScaleFactor()));fitVideo();hud("Zoom "+Math.round(zoom*100)+" %");return true;}public void onScaleEnd(ScaleGestureDetector d){if(playback.current()!=null)prefs.edit().putFloat("zoom:"+playback.current().uri,zoom).apply();}});
  GestureDetector detector=new GestureDetector(this,new GestureDetector.SimpleOnGestureListener(){
   public boolean onDown(MotionEvent e){return true;}
   public boolean onSingleTapConfirmed(MotionEvent e){setControlsVisible(controls.getVisibility()!=View.VISIBLE);scheduleHide();return true;}
   public boolean onDoubleTap(MotionEvent e){if(!prefs.getBoolean("doubleTap",true))return true;float fraction=e.getX()/Math.max(1,stage.getWidth());scheduleHide();if(fraction>.30f&&fraction<.70f)return true;long delta=(fraction<=.30f?-1:1)*step()*1000L;playback.seek(playback.position()+delta);hud((delta<0?"−":"+")+step()+" s");return true;}
  });
  touch.setOnTouchListener(new View.OnTouchListener(){float x,y,brightness;int startPosition,startVolume,direction;boolean moving,pinching;
   public boolean onTouch(View v,MotionEvent e){
    if(locked||isInPictureInPictureMode())return true;
    if(e.getActionMasked()==MotionEvent.ACTION_DOWN)pinching=false;
    if(prefs.getBoolean("pinchZoom",true)){scale.onTouchEvent(e);if(e.getPointerCount()>1||pinching){pinching=true;if(e.getActionMasked()==MotionEvent.ACTION_UP){pinching=false;scheduleHide();}return true;}}
    if(e.getAction()==MotionEvent.ACTION_DOWN){x=e.getX();y=e.getY();startPosition=playback.position();startVolume=playback.volume;brightness=getWindow().getAttributes().screenBrightness;if(brightness<0)try{brightness=android.provider.Settings.System.getInt(getContentResolver(),android.provider.Settings.System.SCREEN_BRIGHTNESS)/255f;}catch(Exception ex){brightness=.5f;}moving=false;direction=0;handler.removeCallbacks(hideControls);}
    if(e.getAction()==MotionEvent.ACTION_MOVE){float dx=e.getX()-x,dy=y-e.getY();if(!moving&&Math.max(Math.abs(dx),Math.abs(dy))>dp(24)){moving=true;direction=Math.abs(dx)>Math.abs(dy)?1:2;MotionEvent cancel=MotionEvent.obtain(e.getDownTime(),e.getEventTime(),MotionEvent.ACTION_CANCEL,e.getX(),e.getY(),0);detector.onTouchEvent(cancel);cancel.recycle();}
     if(moving&&direction==1&&prefs.getBoolean("swipeSeek",true)){long target=Math.max(0,Math.min(playback.duration(),startPosition+(long)(dx/Math.max(1,stage.getWidth())*120000)));hud(clock(target));}
     else if(moving&&direction==2&&x<stage.getWidth()/2&&prefs.getBoolean("brightnessGesture",true)){float value=Math.max(.02f,Math.min(1,brightness+dy/Math.max(1,stage.getHeight())));WindowManager.LayoutParams p=getWindow().getAttributes();p.screenBrightness=value;getWindow().setAttributes(p);hud("Brillo "+Math.round(value*100)+" %");}
     else if(moving&&direction==2&&x>=stage.getWidth()/2&&prefs.getBoolean("volumeGesture",true)){playback.setVolume(startVolume+(int)(dy/Math.max(1,stage.getHeight())*200));hud("Volumen "+playback.volume+" %");}
    }
    if(e.getAction()==MotionEvent.ACTION_UP&&moving){if(direction==1&&prefs.getBoolean("swipeSeek",true))playback.seek(startPosition+(long)((e.getX()-x)/Math.max(1,stage.getWidth())*120000));scheduleHide();return true;}
    if(e.getAction()==MotionEvent.ACTION_CANCEL){moving=false;scheduleHide();return true;}
    if(!moving)detector.onTouchEvent(e);return true;
   }
  });
 }
