 private void seekSettings(){EditText input=new EditText(this);input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);input.setText(String.valueOf(step()));input.setSelectAllOnFocus(true);AlertDialog d=new AlertDialog.Builder(this).setTitle("Segundos por salto").setMessage("Elige de 1 a 120 segundos para el doble toque en los extremos.").setView(input).setPositiveButton("Guardar",null).setNegativeButton("Cancelar",null).create();d.setOnShowListener(x->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{int value=Integer.parseInt(input.getText().toString());if(value<1||value>120)throw new NumberFormatException();prefs.edit().putInt("seekSeconds",value).apply();d.dismiss();if(playerPage)showPlayer();}catch(NumberFormatException e){input.setError("Introduce un número de 1 a 120");}}));d.show();}

 private List<String> playlistNames(){return playlistRepository.names();}
 private List<String> playlistItems(String name){return playlistRepository.items(name);}
 private void savePlaylist(String name,List<String> items){try{playlistRepository.save(name,items);}catch(IllegalStateException e){toast(e.getMessage());}}

 private void playlistNameDialog(String old,VideoItem add){EditText input=new EditText(this);input.setSingleLine(true);input.setText(old==null?"":old);AlertDialog d=dialog(old==null?"Crear lista":"Renombrar lista").setView(input).setPositiveButton("Guardar",null).setNegativeButton("Cancelar",null).create();d.setOnShowListener(x->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String name=input.getText().toString().trim();if(name.isEmpty()||name.length()>80){input.setError("Usa de 1 a 80 caracteres");return;}for(String existing:playlistNames())if(existing.equalsIgnoreCase(name)&&!existing.equals(old)){input.setError("Ya existe una lista con ese nombre");return;}List<String> items=old==null?new ArrayList<>():playlistItems(old);if(add!=null)PlaylistOrder.add(items,add.uri.toString());try{playlistRepository.rename(old,name,items);if(old!=null&&old.equals(selectedPlaylist))selectedPlaylist=name;d.dismiss();if(!playerPage)showLibrary();toast("Lista guardada");}catch(IllegalStateException e){input.setError(e.getMessage());}}));d.show();}
 private void playlistsDialog(){List<String> names=playlistNames();List<String> labels=new ArrayList<>();labels.add("Crear nueva lista");for(String name:names)labels.add(name+" · "+playlistItems(name).size()+" vídeos");dialog("Listas de reproducción").setItems(labels.toArray(new String[0]),(d,i)->{if(i==0)playlistNameDialog(null,null);else playlistMenu(names.get(i-1));}).setNegativeButton("Cerrar",null).show();}
 private void playlistMenu(String name){dialog(name).setItems(new String[]{"Abrir lista","Reproducir lista","Añadir vídeos","Renombrar","Eliminar lista"},(d,i)->{if(i<2){selectedPlaylist=name;selectedFolder=null;favoritesOnly=false;showLibrary();if(i==1){if(visible.isEmpty())toast("No hay vídeos disponibles en esta lista.");else startVideo(new ArrayList<>(visible),0);}}else if(i==2)addVideosDialog(name);else if(i==3)playlistNameDialog(name,null);else dialog("Eliminar lista").setMessage("Se eliminará la lista «"+name+"». Los archivos de vídeo se conservarán.").setPositiveButton("Eliminar lista",(dd,w)->{try{playlistRepository.delete(name);}catch(IllegalStateException e){toast(e.getMessage());return;}if(name.equals(selectedPlaylist))selectedPlaylist=null;showLibrary();}).setNegativeButton("Cancelar",null).show();}).show();}
 private void addVideosDialog(String name){List<VideoItem> available=new ArrayList<>();for(VideoItem v:videos)if(!blocked(v.folder))available.add(v);String[] labels=new String[available.size()];List<String> items=playlistItems(name);boolean[] checked=new boolean[available.size()];for(int i=0;i<available.size();i++){labels[i]=available.get(i).title;checked[i]=items.contains(available.get(i).uri.toString());}dialog("Vídeos de «"+name+"»").setMultiChoiceItems(labels,checked,(d,i,c)->checked[i]=c).setPositiveButton("Guardar",(d,w)->{for(int i=0;i<available.size();i++){String uri=available.get(i).uri.toString();if(checked[i]){PlaylistOrder.add(items,uri);}else items.remove(uri);}savePlaylist(name,items);renderRows();}).setNegativeButton("Cancelar",null).show();}
 private void addToPlaylist(VideoItem item){List<String> names=playlistNames();List<String> labels=new ArrayList<>(names);labels.add("Crear nueva lista");dialog("Añadir a una lista").setItems(labels.toArray(new String[0]),(d,i)->{if(i==names.size())playlistNameDialog(null,item);else{List<String> values=playlistItems(names.get(i));PlaylistOrder.add(values,item.uri.toString());savePlaylist(names.get(i),values);renderRows();toast("Vídeo añadido");}}).show();}
 private void browseFolders(){TreeMap<String,Integer> counts=new TreeMap<>();for(VideoItem v:videos)if(!blocked(v.folder)){String folder=v.folder;while(true){counts.put(folder,counts.getOrDefault(folder,0)+1);int slash=folder.lastIndexOf('/');if(slash<0)break;folder=folder.substring(0,slash);}}List<String> paths=new ArrayList<>(counts.keySet());String[] labels=new String[paths.size()];for(int i=0;i<labels.length;i++)labels[i]=(paths.get(i).isEmpty()?"Almacenamiento":paths.get(i))+" · "+counts.get(paths.get(i))+" vídeos";dialog("Carpetas de vídeos").setItems(labels,(d,i)->{selectedFolder=paths.get(i);selectedPlaylist=null;favoritesOnly=false;showLibrary();}).setNegativeButton("Cerrar",null).show();}
