 private void renameVideo(VideoItem item){EditText name=new EditText(this);name.setSingleLine();name.setText(item.title);AlertDialog dialog=dialog("Renombrar archivo").setView(name).setPositiveButton("Guardar",null).setNegativeButton("Cancelar",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String value=name.getText().toString().trim();if(value.isEmpty()||value.length()>180||value.contains("/")||value.contains("\\")||value.indexOf((char)0)>=0){name.setError("Usa un nombre de archivo válido de 1 a 180 caracteres.");return;}pendingRename=item.uri;renameValue=value;dialog.dismiss();try{if(Build.VERSION.SDK_INT>=30)startIntentSenderForResult(MediaStore.createWriteRequest(getContentResolver(),Collections.singletonList(item.uri)).getIntentSender(),40,null,0,0,0);else if(Build.VERSION.SDK_INT<=28&&checkSelfPermission(Manifest.permission.WRITE_EXTERNAL_STORAGE)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.WRITE_EXTERNAL_STORAGE},42);else commitRename();}catch(Exception e){pendingRename=null;toast("Android no permitió renombrar el archivo.");}}));dialog.show();}
 private void commitRename(){if(pendingRename==null||renameValue==null)return;try{android.content.ContentValues values=new android.content.ContentValues();values.put(MediaStore.MediaColumns.DISPLAY_NAME,renameValue);if(getContentResolver().update(pendingRename,values,null,null)>0){if(playback!=null)playback.renameVideo(pendingRename,renameValue);thumbnails.invalidate();scan();toast("Archivo renombrado");}else toast("No se pudo renombrar el archivo.");pendingRename=null;}catch(SecurityException e){if(Build.VERSION.SDK_INT==29&&e instanceof RecoverableSecurityException)try{startIntentSenderForResult(((RecoverableSecurityException)e).getUserAction().getActionIntent().getIntentSender(),41,null,0,0,0);}catch(Exception ex){pendingRename=null;toast("Android no permitió renombrar el archivo.");}else{pendingRename=null;toast("No tienes permiso para renombrar este archivo.");}}catch(Exception e){pendingRename=null;toast("No se pudo renombrar el archivo.");}}
 private void deleteVideo(VideoItem item){try{if(Build.VERSION.SDK_INT>=30){pendingDelete=item;startIntentSenderForResult(MediaStore.createDeleteRequest(getContentResolver(),Collections.singletonList(item.uri)).getIntentSender(),30,null,0,0,0);return;}if(Build.VERSION.SDK_INT<=28&&checkSelfPermission(Manifest.permission.WRITE_EXTERNAL_STORAGE)!=PackageManager.PERMISSION_GRANTED){pendingDelete=item;requestPermissions(new String[]{Manifest.permission.WRITE_EXTERNAL_STORAGE},32);return;}if(getContentResolver().delete(item.uri,null,null)>0)deleted(item);else toast("El archivo no existe o no se pudo eliminar.");}catch(SecurityException e){if(Build.VERSION.SDK_INT==29&&e instanceof RecoverableSecurityException){try{pendingDelete=item;startIntentSenderForResult(((RecoverableSecurityException)e).getUserAction().getActionIntent().getIntentSender(),31,null,0,0,0);}catch(Exception ex){pendingDelete=null;toast("Android no permitió eliminar el archivo.");}}else{pendingDelete=null;toast("Sin permiso para eliminar este archivo.");}}catch(Exception e){pendingDelete=null;toast("No se pudo eliminar este archivo.");}}
 private void deleted(VideoItem item){scanToken++;String uri=item.uri.toString();videos.removeIf(v->v.uri.equals(item.uri));for(String name:playlistNames()){List<String> values=playlistItems(name);if(values.remove(uri))savePlaylist(name,values);}Set<String> values=new HashSet<>(prefs.getStringSet("favorites",Collections.emptySet()));values.remove(uri);prefs.edit().putStringSet("favorites",values).remove("markers:"+uri).remove("subtitle:"+uri).apply();if(playback!=null)playback.forgetVideo(item.uri);renderRows();scan();toast("Archivo eliminado");}

 private void folders(){TreeSet<String> paths=new TreeSet<>(excluded);for(VideoItem v:videos)if(!v.folder.isEmpty())paths.add(v.folder);String[] names=paths.toArray(new String[0]);boolean[] checked=new boolean[names.length];for(int i=0;i<names.length;i++)checked[i]=excluded.contains(names[i]);new AlertDialog.Builder(this,night?AlertDialog.THEME_DEVICE_DEFAULT_DARK:AlertDialog.THEME_DEVICE_DEFAULT_LIGHT).setTitle("Excluir carpetas y subcarpetas").setMultiChoiceItems(names,checked,(d,i,c)->{if(c)excluded.add(names[i]);else excluded.remove(names[i]);saveFolders();}).setPositiveButton("Listo",(d,w)->renderRows()).setNeutralButton("Añadir ruta",(d,w)->manualFolder()).setNegativeButton("Cerrar",null).show();}
 private void manualFolder(){EditText input=new EditText(this);input.setSingleLine();input.setHint("Movies/Privados");input.setPadding(dp(24),dp(16),dp(24),dp(16));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Ruta de carpeta").setMessage("Escribe la ruta relativa al almacenamiento, por ejemplo Movies/Privados. Incluye sus subcarpetas.").setView(input).setPositiveButton("Excluir",null).setNegativeButton("Cancelar",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String path=normalize(input.getText().toString());if(path.isEmpty()||path.contains("..")){input.setError("Escribe una carpeta válida");return;}excluded.add(path);saveFolders();dialog.dismiss();folders();}));dialog.show();}
